test("period status as of end scenario 2", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "vic", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "floor", "2.00");
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "period-numbering-from", "2026-03-01");
  await ui.setSetting(pg_uma, "terms-C", "3");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "20.00", "from": "2026-03-10"})).toBe(true);
  expect(await ui.addPeriod(pg_uma, {"name": "P1", "from": "2026-03-01", "to": "2026-03-15"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"}));
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "20.00", "date": "2026-03-01"}));
  expect(await ui.editClaim(pg_uma, c_cam_0, {"amount": "1.00"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "void")).toBe(true);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  const c_cam_1 = ui.must(await ui.addClaimTwice(pg_uma, p_cam, {"amount": "25.00", "date": "2026-02-10"}));
  expect(await ui.claimCount(pg_uma, p_cam)).toBe(2);
  expect(await ui.claimAction(pg_uma, c_cam_1, "open")).toBe(true);
  expect(await ui.pasteClaims(pg_uma, "Cam,0.04,,\nAda,0.04,,paste")).toBe(2);
  const c_cam_2 = await ui.claimAt(pg_uma, p_cam, 2);
  const c_ada_0 = await ui.claimAt(pg_uma, p_ada, 0);
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("25.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("5.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-due")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("5.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("VOID");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("25.00");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("5.00");
  await expect(pg_uma.getByTestId("rollup-overdue-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("rollup-overdue-total")).toHaveText("5.00");
  await expect(pg_uma.getByTestId("header-people-count")).toHaveText("3");
  await expect(pg_uma.getByTestId("header-claims-DRAFT-count")).toHaveText("2");
  await expect(pg_uma.getByTestId("header-claims-OPEN-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_uma.getByTestId("header-claims-VOID-count")).toHaveText("1");
  await expect(pg_uma.getByTestId("header-due-total")).toHaveText("5.00");
  await expect(pg_uma.getByTestId("header-overdue-total")).toHaveText("5.00");
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_2, "open")).toBe(true);
  expect(await ui.retire(pg_uma, p_cam, "2026-03-20")).toBe(true);
  await ui.showRetired(pg_uma, true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00", "from": "2026-03-10"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
  await ui.setToday(pg_uma, "2026-05-11");
  expect(await ui.pasteClaims(pg_uma, "Ben,4.00,2026-04-02,\nZed,0.40,2026-02-10,a, b\nAda,0.04,,paste")).toBeNull();
  await ui.refresh(pg_uma);
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("25.04");
  await expect(pg_uma.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("7.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-due")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("5.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("yes");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("VOID");
  await expect(pg_uma.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("0.04");
  await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-due-total")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-due")).toHaveText("2.00");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-status")).toHaveText("OPEN");
  await expect(pg_uma.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_uma.getByTestId("rollup-claimed-total")).toHaveText("25.08");
  await expect(pg_uma.getByTestId("rollup-due-total")).toHaveText("9.00");
