cd /home/daniel/ui-work/runs/202610271-as/sandbox/officehq-angular-spring/src/main/frontend/src/app && python3 - <<'EOF'
p='features/claims/claims.ts'
s=open(p).read()
anchor="/** Whether a claim is handled as open: OPEN or PENDING."
s=s.replace(anchor,"""/**
 * The status the claim had at the end of the date, as its status log records it: its last line logged on or before
 * the date; null when it has lines but none by then (it was added later). With no log at all, its status now.
 */
export function statusOn(claim: Claim, date: string): ClaimStatus | null {
  if (claim.log.length === 0) return claim.status;
  let found: ClaimStatus | null = null;
  for (const line of claim.log) if (line.date <= date) found = line.status;
  return found;
}

"""+anchor,1)
open(p,'w').write(s)
p='features/people/people.ts'
s=open(p).read()
s=s.replace("""/** A CSV field:""","""/**
 * Whether the claim counts in a period's due-total: by the status it had at the end of the period's last day, an OPEN,
 * PENDING or SETTLED one, but one open then and dated within a hold of its person not unless a statement binds it, and
 * one deferred on the sheet's today not at all.
 */
function liveAtEnd(claim: Claim, holds: PersonHold[], today: string | null, end: string): boolean {
  const status = statusOn(claim, end);
  if (status === null || deferred(claim, today)) return false;
  const open = status === 'OPEN' || status === 'PENDING';
  return (open || status === 'SETTLED') && !(open && !bound(claim) && heldOn(holds, claim.date));
}

/** A CSV field:""",1)
s=s.replace("!live(c, person.holds, this.session.today())) continue;\n      const theirs","!liveAtEnd(c, person.holds, this.session.today(), period.to)) continue;\n      const theirs",1)
s=s.replace("import { Claim, Claims, PersonGrade, bound, byListed, claimDue, counts, dueFixed,","import { Claim, Claims, PersonGrade, bound, byListed, claimDue, counts, deferred, dueFixed,",1)
s=s.replace("overdue, sumAmounts } from '../claims/claims';","overdue, statusOn, sumAmounts } from '../claims/claims';",1)
open(p,'w').write(s)
EOF
grep -n "liveAtEnd\|statusOn" features/people/people.ts; sed -n 365,378p features/people/people.ts

